const DMAP2 = {};
const norm = (t) => String(t || "").toLowerCase().replace(/[-_/]/g, " ").replace(/[^a-z0-9\s+]/g, " ").replace(/\s+/g, " ").trim();
// Returns the best matching pack for a question, or null. Longer key phrases win.
export function packFind(q) {
  const t = " " + norm(q) + " "; let best = null, bl = 0;
  for (const p of PACKS) for (const k of p.keys) { const kk = norm(k); if (t.includes(" " + kk + " ") && kk.length > bl) { best = p; bl = kk.length; } }
  return best;
}

export function packScore(q) {
  const t = " " + norm(q) + " "; let best = null, bl = 0;
  for (const p of PACKS) for (const k of p.keys) { const kk = norm(k); if (t.includes(" " + kk + " ") && kk.length > bl) { best = p; bl = kk.length; } }
  return { p: best, len: bl };
}
